SELECT
  COALESCE(TO_CHAR(CAST("id" AS NUMBER(38,0))), '<NULL>') AS k0,
  LOWER(RAWTOHEX(STANDARD_HASH((COALESCE(RTRIM("code"), '<NULL>') || '|~|' || COALESCE(RTRIM("name"), '<NULL>') || '|~|' || COALESCE(TO_CHAR(CAST("amount" AS NUMBER(38,6)), 'FM99999999999999999999999999999999999990.000000'), '<NULL>') || '|~|' || COALESCE(TO_CHAR(CAST("ratio" AS NUMBER(38,6)), 'FM99999999999999999999999999999999999990.000000'), '<NULL>') || '|~|' || COALESCE(TO_CHAR(CAST("units" AS NUMBER(38,0))), '<NULL>') || '|~|' || COALESCE(CASE WHEN "is_active" IS NULL THEN NULL WHEN "is_active" = 0 THEN '0' ELSE '1' END, '<NULL>') || '|~|' || COALESCE(TO_CHAR("born_on", 'YYYY-MM-DD'), '<NULL>') || '|~|' || COALESCE(TO_CHAR("updated_at", 'YYYY-MM-DD HH24:MI:SS.FF6'), '<NULL>')), 'MD5'))) AS row_hash
FROM "dq"."customers"
WHERE (load_dt = '2026-01-01')
